const EMOJI_BASE64_MAP: Record<string, string> = {
    'rocket': 'data:image/png;base64,',
    'fire': 'data:image/png;base64,',
    'heart': 'data:image/png;base64,',
    'smile': 'data:image/png;base64,',
    'smiley': 'data:image/png;base64,',
    'grin': 'data:image/png;base64,',
    'joy': 'data:image/png;base64,',
    'thumbsup': 'data:image/png;base64,',
    'check': 'data:image/png;base64,',
    'warning': 'data:image/png;base64,',
    'info': 'data:image/png;base64,',
    'lock': 'data:image/png;base64,',
    'unlock': 'data:image/png;base64,',
    'key': 'data:image/png;base64,',
    'star': 'data:image/png;base64,',
    'sparkles': 'data:image/png;base64,',
    'gear': 'data:image/png;base64,',
    'bug': 'data:image/png;base64,',
    'memo': 'data:image/png;base64,',
    'package': 'data:image/png;base64,',
    'wrench': 'data:image/png;base64,',
    'bell': 'data:image/png;base64,',
    'bulb': 'data:image/png;base64,',
    'question': 'data:image/png;base64,',
    'exclamation': 'data:image/png;base64,',
    'x': 'data:image/png;base64,',
    'zap': 'data:image/png;base64,',
    'eyes': 'data:image/png;base64,',
    'clap': 'data:image/png;base64,',
    '100': 'data:image/png;base64,',
};
const NATIVE_TO_SHORTCODE: Record<string, string> = {
    '🚀': 'rocket',
    '🔥': 'fire',
    '❤️': 'heart',
    '💖': 'sparkles',
    '⭐': 'star',
    '✅': 'check',
    '⚠️': 'warning',
    'ℹ️': 'info',
    '🔒': 'lock',
    '🔓': 'unlock',
    '🔑': 'key',
    '⚙️': 'gear',
    '🐛': 'bug',
    '📦': 'package',
    '💡': 'bulb',
};

export function parseEmojis(text: string): string {
    if (!text)
        return '';
    let processed = text;
    for (const [native, short] of Object.entries(NATIVE_TO_SHORTCODE)) {
        if (processed.includes(native)) {
            const dataUri = EMOJI_BASE64_MAP[short];
            if (dataUri) {
                const imgTag = `<img class="emoji" alt="${native}" src="${dataUri}" style="height: 1.1em; width: 1.1em; margin: 0 .08em 0 .12em; vertical-align: -0.15em; display: inline-block; object-fit: contain;" />`;
                processed = processed.split(native).join(imgTag);
            }
        }
    }
    return processed.replace(/:([a-zA-Z0-9_\-]+):/g, (match, code) => {
        const lower = code.toLowerCase();
        const dataUri = EMOJI_BASE64_MAP[lower];
        if (dataUri) {
            return `<img class="emoji" alt=":${lower}:" src="${dataUri}" style="height: 1.1em; width: 1.1em; margin: 0 .08em 0 .12em; vertical-align: -0.15em; display: inline-block; object-fit: contain;" />`;
        }
        return match;
    });
}
